import{c as a,Q as e,j as s,m as o}from"./chunks/framework.DOi4mjdC.js";const d="/assets/%E5%8A%9F%E8%83%BD%E7%A4%BA%E4%BE%8B.lB1zOiHY.png",r="/assets/%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B%E5%9B%BE.CTrWrnge.png",u=JSON.parse('{"title":"BroadCastVecToMM(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"BroadCastVecToMM\\\\(ISASI\\\\)","slug":"broadcastvectommisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/BroadCastVecToMM(ISASI).md","filePath":"api/SIMD-API/基础API/Memory数据搬运/BroadCastVecToMM(ISASI).md"}'),l={name:"api/SIMD-API/基础API/Memory数据搬运/BroadCastVecToMM(ISASI).md"};function n(i,t,c,p,h,b){return e(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="broadcastvectomm-isasi" tabindex="-1">BroadCastVecToMM(ISASI) <a class="header-anchor" href="#broadcastvectomm-isasi" aria-label="Permalink to &quot;BroadCastVecToMM\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将矢量数据广播到矩阵中，每个数据块中的每16个elements会被连续复制16次；当前支持的数据传输通路：VECIN/VECCALC/VECOUT-&gt;CO1。</p><p><strong>图 1</strong> 功能示例<br><img src="'+d+`" alt="" title="功能示例"></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void BroadCastVecToMM(const LocalTensor&lt;T&gt; &amp;dst, const LocalTensor&lt;U&gt; &amp;src, const int32_t blockCount, const uint8_t blockLen, const uint8_t srcGap, const uint8_t dstGap)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst的数据类型。 Atlas 推理系列产品AI Core，支持的数据类型为：half/int16_t/uint16_t</td></tr><tr><td>U</td><td>src的数据类型。 Atlas 推理系列产品AI Core，支持的数据类型为：half/int16_t/uint16_t</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，结果矩阵，类型为LocalTensor，支持的TPosition为CO1。 LocalTensor的起始地址需要256个元素对齐。 支持的数据类型为：half/float/int32_t。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，输入矢量，类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 支持的数据类型需要与dst一致。</td></tr><tr><td>blockCount</td><td>输入</td><td>指定该指令包含的连续广播数据块个数，取值范围：blockCount∈[1, 255]。</td></tr><tr><td>blockLen</td><td>输入</td><td>指定该指令每个连续广播数据块长度，单位为16个elements。取值范围：blockLen∈[1, 255]。</td></tr><tr><td>srcGap</td><td>输入</td><td>源操作数，相邻连续数据块的间隔（前面一个数据块的尾与后面数据块的头的间隔），单位为datablock(32Bytes)。</td></tr><tr><td>dstGap</td><td>输入</td><td>目的操作数，相邻连续数据块间的间隔（前面一个数据块的尾与后面数据块的头的间隔），单位为256个elements。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例中，输入bias形状为[1, 32]，输出c的形状为[32, 32]，格式为Nz。</p><p><strong>图 2</strong> 调用示例图<br><img src="`+r+`" alt="" title="调用示例图"></p><p>本示例仅展示样例中的部分代码。如需运行，请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/00_data_movement/broadcast_ub2l0c" target="_blank" rel="noreferrer">BroadCastVecToMM样例</a>实现完整的代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// brcLocal为TPosition::CO1上的float类型的LocalTensor，srcLocal为TPosition::VECIN上的float类型的LocalTensor</span></span>
<span class="line"><span>// blockCount = 1, blockLen = 1. 连续广播的数据块个数为1，每个数据块包含16个elements，共输出256个elements</span></span>
<span class="line"><span>// srcGap = 0, dstGap = 1. 源操作数与目的操作数之间连续</span></span>
<span class="line"><span>AscendC::BroadCastVecToMM(brcLocal, srcLocal, 1, 1, 0, 1)</span></span></code></pre></div>`,20)])])}const _=a(l,[["render",n]]);export{u as __pageData,_ as default};
